// Generates the DESKTOP copy of the shared call and competitor logic from the web app's TypeScript, so the two can never drift apart.
//
//   node scripts/port_calls_desktop.mjs                 (from raptor-app/)  -> writes <PC app>/raptor-ui/src/pages/{calls,competitors}/shared/
//   node scripts/port_calls_desktop.mjs <pages folder>  to write somewhere else
//
// It only strips the types and rewrites the import paths. Never edit the generated files by hand: change the web source and run this again.
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const ts = require('typescript');
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
// by default the PC app's folder next to this repository; give another as the first argument or in RAPTOR_DESKTOP_PAGES
const PAGES = path.resolve(process.argv[2] || process.env.RAPTOR_DESKTOP_PAGES || path.join(ROOT, '../../shoonya origins tech/Raptor B2B/raptor-ui/src/pages'));
const HEADER = '// GENERATED by raptor-app/scripts/port_calls_desktop.mjs from the web app\'s TypeScript. Do not edit here: change the web source and run the script again.\n';

for (const area of ['calls', 'competitors']) {
  const source = path.join(ROOT, 'src/lib', area);
  const out = path.join(PAGES, area, 'shared');
  fs.mkdirSync(out, { recursive: true });
  const written = [];
  for (const name of fs.readdirSync(source).filter((f) => f.endsWith('.ts'))) {
    let js = ts.transpileModule(fs.readFileSync(path.join(source, name), 'utf8'), {
      fileName: name, compilerOptions: { module: ts.ModuleKind.ESNext, target: ts.ScriptTarget.ES2020, removeComments: false },
    }).outputText;
    js = js.replace(/(['"])\.\.\/calls\/([\w-]+)\.ts\1/g, "'../../calls/shared/$2.js'");    // the competitor logic uses the call logic
    js = js.replace(/(from\s+['"]\.\/[\w-]+)\.ts(['"])/g, '$1.js$2');
    fs.writeFileSync(path.join(out, name.replace(/\.ts$/, '.js')), HEADER + js.replace(/\r\n/g, '\n'));
    written.push(name.replace(/\.ts$/, '.js'));
  }
  console.log(`wrote ${written.length} files into ${out}: ${written.join(', ')}`);
}
